<?php
require_once __DIR__ . "/includes/auth.php";auth_start_session();$user=require_role("admin");require_once __DIR__ . "/db.php";
function dh($v){return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,"UTF-8");}
$counts=[];
foreach(["students"=>"SELECT COUNT(*) FROM students","events"=>"SELECT COUNT(*) FROM events","registrations"=>"SELECT COUNT(*) FROM registrations"] as $key=>$sql){$s=$pdo->prepare($sql);$s->execute();$counts[$key]=(int)$s->fetchColumn();}
$s=$pdo->prepare("SELECT r.registration_id,s.full_name,s.email,r.registration_date FROM registrations r JOIN students s ON s.student_id=r.student_id ORDER BY r.registration_date DESC LIMIT 10");$s->execute();$recent=$s->fetchAll();
$a=$pdo->prepare("SELECT a.audit_id,a.action,a.details,a.created_at,s.full_name FROM audit_logs a LEFT JOIN students s ON s.student_id=a.user_id ORDER BY a.created_at DESC LIMIT 20");$a->execute();$logs=$a->fetchAll();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>StudentHub | Admin Dashboard</title><link rel="stylesheet" href="css/style.css"></head><body>
<header class="site-header"><div class="header-inner"><a class="site-title" href="admin.php">StudentHub Admin</a><nav class="main-nav"><a href="admin.php">Dashboard</a><a href="manage_students.php">Students</a><a href="manage_events.php">Events</a><a href="logout.php">Logout</a></nav></div></header>
<main class="page-container"><section class="intro-panel"><p class="eyebrow">Practical 14</p><h1>Administrator Dashboard</h1><p>Welcome, <?=dh($user["name"])?>. Database statistics and activity are shown below.</p></section>
<section class="data-grid"><article class="data-card"><h2>Students</h2><p class="stat-number"><?=dh($counts["students"])?></p><a href="manage_students.php">Manage students</a></article><article class="data-card"><h2>Events</h2><p class="stat-number"><?=dh($counts["events"])?></p><a href="manage_events.php">Manage events</a></article><article class="data-card"><h2>Registrations</h2><p class="stat-number"><?=dh($counts["registrations"])?></p><a href="database.php">View database</a></article></section>
<section class="section-block"><h2>Latest Registrations</h2><div class="table-wrap"><table><thead><tr><th>ID</th><th>Student</th><th>Email</th><th>Date</th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><?=dh($r["registration_id"])?></td><td><?=dh($r["full_name"])?></td><td><?=dh($r["email"])?></td><td><?=dh($r["registration_date"])?></td></tr><?php endforeach;?><?php if(!$recent):?><tr><td colspan="4">No registrations yet.</td></tr><?php endif;?></tbody></table></div></section>
<section class="section-block"><h2>Audit Log</h2><div class="table-wrap"><table><thead><tr><th>ID</th><th>Admin/User</th><th>Action</th><th>Details</th><th>Time</th></tr></thead><tbody><?php foreach($logs as $l):?><tr><td><?=dh($l["audit_id"])?></td><td><?=dh($l["full_name"]??"Deleted user")?></td><td><?=dh($l["action"])?></td><td><?=dh($l["details"])?></td><td><?=dh($l["created_at"])?></td></tr><?php endforeach;?><?php if(!$logs):?><tr><td colspan="5">No audit entries yet.</td></tr><?php endif;?></tbody></table></div></section>
</main><footer class="site-footer"><p>StudentHub · Practicals 2–15 cumulative project</p></footer></body></html>